-- Part 1 of 10. Run the parts in order.
-- Fixtures read from public pages on 2026-11-13: 1865 fixtures at 453 grounds.
-- Generated by collector/make-sql.mjs. Safe to run twice.

-- Lets fixtures come from any named source (one per website or feed), not a fixed short list.
-- Safe to re-run.
alter table public.fixtures drop constraint if exists fixtures_source_check;
alter table public.fixtures add constraint fixtures_source_check check (source ~ '^[a-z][a-z0-9-]*$');
-- Some sources give the day of a fixture but not its start time (a race meeting, a game not yet timed).
-- Those are stored at midday with time_known = false, and the app shows "Time TBC" instead of a clock time.
alter table public.fixtures add column if not exists time_known boolean not null default true;

on conflict (name, county) do nothing;
